  "test_path": "tests/test_telemetry_process_name.py",
  "test": "import os

from browser_use.telemetry.service import ProductTelemetry
from browser_use.telemetry.views import BaseTelemetryEvent


def test_process_name_is_sent_in_telemetry():
    # Ensure the env var is set for the test
    os.environ['BROWSER_USE_PROCESS_NAME'] = 'testproc'

    # Create a dummy PostHog client to capture calls
    class DummyClient:
        def __init__(self):
            self.captured = []
        def capture(self, distinct_id, event, properties):
            self.captured.append((distinct_id, event, properties))
        def flush(self):
            pass

    telemetry = ProductTelemetry()
    telemetry._posthog_client = DummyClient()

    event = BaseTelemetryEvent(name="unit_test_event", properties={"foo": "bar"})
    telemetry.capture(event)

    # Verify that the captured properties include the injected process_name
    assert any(
        isinstance(props, dict) and props.get("process_name") == "testproc"
        for _, _, props in telemetry._posthog_client.captured
    )
"
